def get_cells_per_row(input_grid):
    """Get list of (row, value) for each non-background cell, sorted by column."""
    cells = []
    for r in range(len(input_grid)):
        row_cells = []
        for c in range(len(input_grid[0])):
            if input_grid[r][c] != 0:
                row_cells.append((c, input_grid[r][c]))
        row_cells.sort()  # Sort by column
        cells.append(row_cells)
    return cells

def sort_row_cells_by_value(col_list):
    """Sort cells in a row by value, preserving count of each value. Returns sorted [(col, value)]."""
    # Group by value
    by_value = {}
    for col, val in col_list:
        by_value.setdefault(val, []).append(col)
    # Sort values
    sorted_values = sorted(by_value.keys())
    # Collect all cells with value, then sort by (value, original_col)
    result = []
    for val in sorted_values:
        for col in sorted(by_value[val]):
            result.append((col, val))
    return result

