from collections import deque

def connected_components(grid):
    """Returns list of objects as dicts with sorted cells."""
    if not grid or not grid[0]:
        return []
    visited = [[False] * len(grid[0]) for _ in range(len(grid))]
    components = []
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != 0 and not visited[r][c]:
                value = grid[r][c]
                cells = []
                queue = deque([(r, c)])
                visited[r][c] = True
                while queue:
                    cr, cc = queue.popleft()
                    cells.append((cr, cc))
                    for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                            if not visited[nr][nc] and grid[nr][nc] == value:
                                visited[nr][nc] = True
                                queue.append((nr, nc))
                components.append({'value': value, 'cells': sorted(cells)})
    return components

